/** ****************************************************************************
 * OtherItem.java
 * Kevin Bell
 *
 * This class program simulates inventory sales for non-food items.
 **************************************************************************** */
package inventorysales;

public class OtherItem extends Inventory {

    public OtherItem(int inventoryID, int itemQuantityOnHand, String itemName,
            double unitCost) {
        super(inventoryID, itemQuantityOnHand, itemName, unitCost);
    } // end constructor method 
//******************************************************************************

    @Override
    public double taxCalc(double unitCost) {
        double taxAmount = unitCost * ITEM_TAX;
        return taxAmount;
    } // end taxCalc method
//******************************************************************************

    @Override
    public double calcCost(int qty) {
        if (itemQuantityOnHand >= qty) {
            double subTotal = (qty * unitCost);
            double tax = taxCalc(subTotal);
            double total = (tax + subTotal);
            itemQuantityOnHand = (itemQuantityOnHand - qty);
            System.out.printf("That costs $%1.2f\n", total);
            display();
            return total;
        } else {
            System.out.println("Not enough quantity on hand to sell");
            return 0;
        }// end if/else condition 
    } // end calcCost method
} // end OtherItem class

/** ****************************************************************************
 * Tax.java
 * Kevin Bell
 *
 * This interface simulates tax on inventory sales for food & non-food items
 **************************************************************************** */
package inventorysales;

public interface Tax {

    double FOOD_TAX = .04;
    double ITEM_TAX = .10;

    double taxCalc(double unitCost);
} // end interface Tax

/** ****************************************************************************
 * InventorySales.java
 * Kevin Bell
 *
 * This driver program simulates inventory sales for food & non-food items.
 **************************************************************************** */
package inventorysales;

import java.util.*;

public class InventorySales {

    public static void main(String[] args) {
        System.out.println("Ch 14 Sales by Kevin Bell");
        ArrayList<Inventory> inventory = new ArrayList<>();
        // adding anonymous objects to arrayList
        inventory.add(new Food(1234, 50, "lg soda", 2.50));
        inventory.add(new Food(2345, 30, "donuts", 5));
        inventory.add(new OtherItem(9876, 30, "metal straw", 1.50));
        inventory.add(new OtherItem(8765, 30, "sunglasses", 6.75));
        for (Inventory inventoryStock : inventory) {
            System.out.println("");
            inventoryStock.display();
            System.out.print("How many do you want to purchase? ");
            Scanner computerKeyboardInput = new Scanner(System.in);
            int qty = computerKeyboardInput.nextInt();
            inventoryStock.calcCost(qty);
        } // end for-each loop
    } // end main method
} // end InventorySales class

/** ****************************************************************************
 * Inventory.java
 * Kevin Bell
 *
 * This super class program simulates inventory sales for food & non-food items.
 **************************************************************************** */
package inventorysales;

public abstract class Inventory implements Tax {

    int inventoryID, itemQuantityOnHand;
    String itemName;
    double unitCost;
//******************************************************************************

    public Inventory() {
    } // end zero-parameter constructor

    public Inventory(int inventoryID, int itemQuantityOnHand, String itemName,
            double unitCost) {
        this.inventoryID = inventoryID;
        this.itemQuantityOnHand = itemQuantityOnHand;
        this.itemName = itemName;
        this.unitCost = unitCost;
    } // end constructor
//******************************************************************************

    public void display() {
        System.out.printf("Inventory #%d, name %s, costs $%3.2f, there are %d on "
                + "hand\n", inventoryID, itemName, unitCost, itemQuantityOnHand);
    } // end display method
//******************************************************************************

    public abstract double calcCost(int qty);
} // end Inventory class

/** ****************************************************************************
 * Food.java
 * Kevin Bell
 *
 * This class program simulates inventory sales for food.
 **************************************************************************** */
package inventorysales;

public class Food extends Inventory {

    public Food(int inventoryID, int itemQuantityOnHand, String itemName,
            double unitCost) {
        super(inventoryID, itemQuantityOnHand, itemName, unitCost);
    } // end constructor method    
//******************************************************************************

    @Override
    public double taxCalc(double unitCost) {
        double taxAmount = unitCost * FOOD_TAX;
        return taxAmount;
    } // end taxCalc method
//******************************************************************************

    @Override
    public double calcCost(int qty) {
        if (itemQuantityOnHand >= qty) {
            double subTotal = (qty * unitCost);
            double tax = taxCalc(subTotal);
            double total = (tax + subTotal);
            itemQuantityOnHand = (itemQuantityOnHand - qty);
            System.out.printf("That costs $%1.2f\n", total);
            display();
            return total;
        } else {
            System.out.println("Not enough quantity on hand to sell");
            return 0;
        }// end if/else condition 
    } // end calcCost method
} // end Food class
